fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    // Pre-allocate a result vector of the same length as the input
    let mut result: Vec<char> = Vec::with_capacity(s.len());

    for &ch in s.iter() {
        // Check if `ch` is in the ASCII uppercase range 'A'..='Z'
        if ch >= 'A' && ch <= 'Z' {
            // ASCII codes for 'A'..'Z' are 65..=90, 'a'..'z' are 97..=122,
            // so adding 32 converts uppercase to lowercase.
            let lower = (ch as u8 + 32) as char;
            result.push(lower);
        } else {
            // Non-ASCII-uppercase characters remain unchanged
            result.push(ch);
        }
    }

    result
}